#include "preprocessor.h"
char *position_text(Position position) { return ml_format("%s:%d", position.file, position.line); }
bool builtin(const char *name) { return word_in("__LINE__ __FILE__ __COUNTER__", name); }
char *signature(Macro *macro) {
    if (!macro->function)
        return (char *)macro->name;
    Text result = {0};
    text_add(&result, macro->name);
    text_char(&result, '(');
    for (int i = 0; i < macro->parameters.count; ++i) {
        if (i)
            text_add(&result, ", ");
        text_add(&result, macro->variadic && i + 1 == macro->parameters.count
                              ? "..."
                              : macro->parameters.items[i]);
    }
    text_char(&result, ')');
    return text_value(&result);
}
char *check_name(Tokens tokens, const char *directive) {
    if (!tokens.count)
        return ml_format("no macro name given in #%s directive", directive);
    if (!equal(tokens.items[0].kind, "identifier"))
        return "macro names must be identifiers";
    const char *name = tokens.items[0].spelling;
    if (equal(name, "defined"))
        return "\"defined\" cannot be used as a macro name";
    if (builtin(name))
        return ml_format(equal(directive, "define") ? "cannot redefine builtin macro \"%s\""
                                                    : "cannot undefine builtin macro \"%s\"",
                         name);
    return NULL;
}
Macro *parse_definition(Tokens tokens, Position position, bool main_file, char **error) {
    *error = check_name(tokens, "define");
    if (*error)
        return NULL;
    Macro *macro = ml_alloc(sizeof(*macro));
    macro->name = tokens.items[0].spelling;
    macro->position = position;
    macro->main_file = main_file;
    const char *variadic_error =
        "\"__VA_ARGS__\" can only appear in the expansion of a variadic macro";
    if (equal(macro->name, "__VA_ARGS__")) {
        *error = (char *)variadic_error;
        return NULL;
    }
    int index = 1;
    if (index < tokens.count && equal(tokens.items[index].spelling, "(") &&
        !tokens.items[index].space) {
        macro->function = true;
        ++index;
        if (index == tokens.count) {
            *error = "missing ')' in macro parameter list";
            return NULL;
        }
        if (equal(tokens.items[index].spelling, ")"))
            ++index;
        else
            while (true) {
                if (index == tokens.count) {
                    *error = "missing ')' in macro parameter list";
                    return NULL;
                }
                Token token = tokens.items[index++];
                const char *parameter = token.spelling;
                if (equal(parameter, "...")) {
                    macro->variadic = true;
                    parameter = "__VA_ARGS__";
                } else if (equal(token.kind, "identifier")) {
                    if (equal(parameter, "__VA_ARGS__")) {
                        *error = (char *)variadic_error;
                        return NULL;
                    }
                    if (string_member(macro->parameters, parameter)) {
                        *error = ml_format("duplicate macro parameter \"%s\"", parameter);
                        return NULL;
                    }
                } else {
                    *error = ml_format("expected parameter name, found \"%s\"", parameter);
                    return NULL;
                }
                PUSH(macro->parameters, (char *)parameter);
                if (index == tokens.count) {
                    *error = "missing ')' in macro parameter list";
                    return NULL;
                }
                const char *next = tokens.items[index++].spelling;
                if (equal(next, ")"))
                    break;
                if (macro->variadic) {
                    *error = ml_format("expected ')' after \"...\", found \"%s\"", next);
                    return NULL;
                }
                if (!equal(next, ",")) {
                    *error = ml_format("expected ',' or ')', found \"%s\"", next);
                    return NULL;
                }
            }
    }
    for (int i = index; i < tokens.count; ++i)
        PUSH(macro->replacement, tokens.items[i]);
    if (macro->replacement.count) {
        macro->replacement.items[0].space = false;
        if (equal(macro->replacement.items[0].spelling, "##") ||
            equal(macro->replacement.items[macro->replacement.count - 1].spelling, "##")) {
            *error = "'##' cannot appear at either end of a macro expansion";
            return NULL;
        }
    }
    for (int i = 0; i < macro->replacement.count; ++i) {
        Token token = macro->replacement.items[i];
        if (equal(token.kind, "identifier") && equal(token.spelling, "__VA_ARGS__") &&
            !macro->variadic) {
            *error = (char *)variadic_error;
            return NULL;
        }
        if (equal(token.spelling, "#") && macro->function &&
            (i + 1 == macro->replacement.count ||
             !equal(macro->replacement.items[i + 1].kind, "identifier") ||
             !string_member(macro->parameters, macro->replacement.items[i + 1].spelling))) {
            *error = "'#' is not followed by a macro parameter";
            return NULL;
        }
    }
    return macro;
}
bool identical(Macro *left, Macro *right) {
    if (left->function != right->function || left->variadic != right->variadic ||
        left->parameters.count != right->parameters.count ||
        left->replacement.count != right->replacement.count)
        return false;
    for (int i = 0; i < left->parameters.count; ++i)
        if (!equal(left->parameters.items[i], right->parameters.items[i]))
            return false;
    for (int i = 0; i < left->replacement.count; ++i)
        if (!equal(left->replacement.items[i].spelling, right->replacement.items[i].spelling) ||
            left->replacement.items[i].space != right->replacement.items[i].space)
            return false;
    return true;
}

#include "preprocessor.h"
typedef struct Pending {
    Token token;
    struct Pending *next;
} Pending;
typedef struct {
    bool paste;
    Tokens tokens;
    Token operator_token;
} SubstitutionItem;
typedef struct {
    SubstitutionItem *items;
    int count, capacity;
} ItemList;
static Token stringize(Tokens raw, Token hash) {
    Token result = {0};
    result.kind = "string";
    result.space = hash.space;
    Text text = {0};
    text_char(&text, '"');
    for (int i = 0; i < raw.count; ++i) {
        Token token = raw.items[i];
        if (i && token.space)
            text_char(&text, ' ');
        for (const char *c = token.spelling; *c; ++c) {
            if ((equal(token.kind, "string") || equal(token.kind, "character")) &&
                (*c == '\\' || *c == '"'))
                text_char(&text, '\\');
            text_char(&text, *c);
        }
    }
    text_char(&text, '"');
    result.spelling = text_value(&text);
    return result;
}
static Tokens paste(Preprocessor *p, Inclusion *inclusion, Token left, Token right,
                    Token invocation) {
    Tokens result = {0};
    if (equal(left.kind, "placemarker")) {
        right.space = left.space;
        PUSH(result, right);
        return result;
    }
    if (equal(right.kind, "placemarker")) {
        PUSH(result, left);
        return result;
    }
    char *spelling = ml_format("%s%s", left.spelling, right.spelling);
    const char *kind = single_token(spelling);
    if (kind) {
        Token token = {kind, spelling, 0, left.space, {0}};
        token.hide = names_intersection(left.hide, right.hide);
        PUSH(result, token);
    } else {
        diagnostic(p, display_position(inclusion, invocation.line), "error",
                   ml_format("pasting \"%s\" and \"%s\" does not give a valid preprocessing token",
                             left.spelling, right.spelling));
        right.space = false;
        PUSH(result, left);
        PUSH(result, right);
    }
    return result;
}
static int parameter_index(Macro *macro, const char *name) {
    for (int i = 0; i < macro->parameters.count; ++i)
        if (equal(macro->parameters.items[i], name))
            return i;
    return -1;
}
static Tokens substitute(Preprocessor *p, Inclusion *inclusion, Macro *macro, Token invocation,
                         TokenGroups raw, StringList hide) {
    Tokens *expanded = ml_alloc((size_t)raw.count * sizeof(*expanded));
    bool *cached = ml_alloc((size_t)raw.count * sizeof(*cached));
    ItemList items = {0};
    for (int i = 0; i < macro->replacement.count; ++i) {
        Token token = macro->replacement.items[i];
        SubstitutionItem item = {0};
        if (equal(token.spelling, "#") && macro->function) {
            Token parameter = macro->replacement.items[++i];
            Token quoted = stringize(raw.items[parameter_index(macro, parameter.spelling)], token);
            PUSH(item.tokens, quoted);
        } else if (equal(token.spelling, "##")) {
            item.paste = true;
            item.operator_token = token;
        } else {
            int index =
                equal(token.kind, "identifier") ? parameter_index(macro, token.spelling) : -1;
            if (index >= 0) {
                bool adjacent = (i > 0 && equal(macro->replacement.items[i - 1].spelling, "##")) ||
                                (i + 1 < macro->replacement.count &&
                                 equal(macro->replacement.items[i + 1].spelling, "##"));
                Tokens sequence;
                if (adjacent)
                    sequence = raw.items[index];
                else {
                    if (!cached[index]) {
                        expanded[index] = expand(p, inclusion, raw.items[index]);
                        cached[index] = true;
                    }
                    sequence = expanded[index];
                }
                item.tokens = copy_tokens(sequence);
                if (!item.tokens.count) {
                    Token marker = {"placemarker", "", 0, token.space, {0}};
                    PUSH(item.tokens, marker);
                } else
                    item.tokens.items[0].space = token.space;
            } else
                PUSH(item.tokens, token);
        }
        PUSH(items, item);
    }
    Tokens combined = {0};
    for (int i = 0; i < items.count; ++i) {
        SubstitutionItem item = items.items[i];
        if (!item.paste) {
            for (int j = 0; j < item.tokens.count; ++j)
                PUSH(combined, item.tokens.items[j]);
        } else {
            Token left = combined.items[--combined.count];
            SubstitutionItem right = items.items[++i];
            Tokens sequence = right.tokens;
            if (right.paste) {
                sequence = (Tokens){0};
                PUSH(sequence, right.operator_token);
            }
            Tokens pasted = paste(p, inclusion, left, sequence.items[0], invocation);
            for (int j = 0; j < pasted.count; ++j)
                PUSH(combined, pasted.items[j]);
            for (int j = 1; j < sequence.count; ++j)
                PUSH(combined, sequence.items[j]);
        }
    }
    Tokens result = {0};
    bool carry = false;
    for (int i = 0; i < combined.count; ++i) {
        Token token = combined.items[i];
        if (equal(token.kind, "placemarker")) {
            carry = carry || token.space;
            continue;
        }
        token.space = token.space || carry;
        carry = false;
        token.line = invocation.line;
        token.hide = names_union(token.hide, hide);
        PUSH(result, token);
    }
    if (result.count)
        result.items[0].space = invocation.space;
    return result;
}
Tokens expand(Preprocessor *p, Inclusion *inclusion, Tokens tokens) {
    Pending *input = NULL;
    for (int i = tokens.count - 1; i >= 0; --i) {
        Pending *node = ml_alloc(sizeof(*node));
        node->token = tokens.items[i];
        node->next = input;
        input = node;
    }
    Tokens result = {0};
    while (input) {
        Token invocation = input->token;
        input = input->next;
        const char *name = invocation.spelling;
        if (!equal(invocation.kind, "identifier") || string_member(invocation.hide, name)) {
            PUSH(result, invocation);
            continue;
        }
        if (builtin(name)) {
            Token token = {0};
            token.line = invocation.line;
            token.space = invocation.space;
            token.kind = equal(name, "__FILE__") ? "string" : "number";
            if (equal(name, "__LINE__")) {
                ++p->builtin_counts[2];
                token.spelling = ml_format("%d", display_position(inclusion, invocation.line).line);
            } else if (equal(name, "__FILE__")) {
                ++p->builtin_counts[1];
                token.spelling = ml_format("\"%s\"", inclusion->display_file);
            } else {
                ++p->builtin_counts[0];
                token.spelling = ml_format("%d", p->counter++);
            }
            PUSH(result, token);
            continue;
        }
        Macro *macro = find_macro(p, name);
        if (!macro) {
            PUSH(result, invocation);
            continue;
        }
        StringList hide = invocation.hide;
        TokenGroups raw = {0};
        if (macro->function) {
            if (!input || !equal(input->token.spelling, "(")) {
                PUSH(result, invocation);
                continue;
            }
            TokenGroups arguments = {0};
            Tokens argument = {0}, commas = {0};
            PUSH(arguments, argument);
            int depth = 0;
            Pending *close = input->next;
            for (; close; close = close->next) {
                Token token = close->token;
                if (equal(token.spelling, ")") && depth == 0)
                    break;
                if (equal(token.spelling, ",") && depth == 0) {
                    PUSH(commas, token);
                    Tokens next = {0};
                    PUSH(arguments, next);
                } else {
                    if (equal(token.spelling, "("))
                        ++depth;
                    else if (equal(token.spelling, ")"))
                        --depth;
                    PUSH(arguments.items[arguments.count - 1], token);
                }
            }
            int k = arguments.count, n = macro->parameters.count - (macro->variadic ? 1 : 0);
            char *error = NULL;
            if (!close)
                error = ml_format("unterminated argument list invoking macro \"%s\"", name);
            else if (!macro->variadic && n == 0 && !(k == 1 && !arguments.items[0].count))
                error = ml_format("macro \"%s\" passed %d arguments, but takes just 0", name, k);
            else if (k < n)
                error =
                    ml_format("macro \"%s\" requires %d arguments, but only %d given", name, n, k);
            else if (k > n && !macro->variadic)
                error =
                    ml_format("macro \"%s\" passed %d arguments, but takes just %d", name, k, n);
            if (error) {
                diagnostic(p, display_position(inclusion, invocation.line), "error", error);
                PUSH(result, invocation);
                continue;
            }
            hide = names_intersection(invocation.hide, close->token.hide);
            for (int i = 0; i < n; ++i)
                PUSH(raw, arguments.items[i]);
            if (macro->variadic) {
                Tokens variadic = {0};
                for (int i = n; i < arguments.count; ++i) {
                    if (i > n)
                        PUSH(variadic, commas.items[i - 1]);
                    for (int j = 0; j < arguments.items[i].count; ++j)
                        PUSH(variadic, arguments.items[i].items[j]);
                }
                PUSH(raw, variadic);
            }
            input = close->next;
        }
        StringList own = {0};
        PUSH(own, (char *)name);
        hide = names_union(hide, own);
        Tokens replacement = substitute(p, inclusion, macro, invocation, raw, hide);
        ++macro->expanded;
        if (!replacement.count && invocation.space && input)
            input->token.space = true;
        for (int i = replacement.count - 1; i >= 0; --i) {
            Pending *node = ml_alloc(sizeof(*node));
            node->token = replacement.items[i];
            node->next = input;
            input = node;
        }
    }
    return result;
}

#include "preprocessor.h"
typedef struct {
    Tokens tokens;
    int index;
    jmp_buf jump;
    char *error;
} ExpressionParser;
static void expression_error(ExpressionParser *parser, const char *message) {
    parser->error = (char *)message;
    longjmp(parser->jump, 1);
}
static int digit_value(char c) {
    if (c >= '0' && c <= '9')
        return c - '0';
    if (c >= 'a' && c <= 'f')
        return c - 'a' + 10;
    if (c >= 'A' && c <= 'F')
        return c - 'A' + 10;
    return -1;
}
static int64_t integer_constant(ExpressionParser *parser, const char *spelling) {
    char *text = ml_text(spelling, strlen(spelling));
    const char *suffixes[] = {"ll", "LL", "l", "L"};
    for (int i = 0; i < 4; ++i) {
        size_t n = strlen(text), s = strlen(suffixes[i]);
        if (n > s && equal(text + n - s, suffixes[i])) {
            text[n - s] = 0;
            break;
        }
    }
    int base = 10;
    size_t first = 0, n = strlen(text);
    bool valid = n > 0;
    if (n >= 2 && text[0] == '0' && (text[1] == 'x' || text[1] == 'X')) {
        base = 16;
        first = 2;
        if (first == n)
            valid = false;
    } else if (n && text[0] == '0')
        base = 8;
    else if (!n || text[0] < '1' || text[0] > '9')
        valid = false;
    for (size_t i = first; i < n; ++i) {
        int digit = digit_value(text[i]);
        if (digit < 0 || digit >= base)
            valid = false;
    }
    if (!valid)
        expression_error(parser, ml_format("invalid integer constant \"%s\"", spelling));
    int64_t value = 0;
    for (size_t i = first; i < n; ++i)
        value = value * base + digit_value(text[i]);
    return value;
}
static int64_t character_constant(ExpressionParser *parser, const char *spelling) {
    size_t length = strlen(spelling) - 2;
    const char *body = spelling + 1;
    if (length == 1 && body[0] != '\'' && body[0] != '\\')
        return (unsigned char)body[0];
    if (length == 2 && body[0] == '\\') {
        const char characters[] = {'n', 't', '\\', '\'', '"', '0'};
        const int values[] = {10, 9, 92, 39, 34, 0};
        for (int i = 0; i < 6; ++i)
            if (body[1] == characters[i])
                return values[i];
    }
    expression_error(parser, ml_format("invalid character constant %s", spelling));
    return 0;
}
static int precedence(const char *op) {
    if (equal(op, "||"))
        return 1;
    if (equal(op, "&&"))
        return 2;
    if (equal(op, "|"))
        return 3;
    if (equal(op, "^"))
        return 4;
    if (equal(op, "&"))
        return 5;
    if (equal(op, "==") || equal(op, "!="))
        return 6;
    if (word_in("< > <= >=", op))
        return 7;
    if (equal(op, "<<") || equal(op, ">>"))
        return 8;
    if (equal(op, "+") || equal(op, "-"))
        return 9;
    if (word_in("* / %", op))
        return 10;
    return 0;
}
static ConditionExpr *node(const char *kind) {
    ConditionExpr *result = ml_alloc(sizeof(*result));
    result->kind = kind;
    return result;
}
static const char *peek(ExpressionParser *parser) {
    return parser->index == parser->tokens.count ? ""
                                                 : parser->tokens.items[parser->index].spelling;
}
static ConditionExpr *expression(ExpressionParser *);
static ConditionExpr *primary(ExpressionParser *parser) {
    if (parser->index == parser->tokens.count)
        expression_error(parser, "expected value at end of expression");
    Token token = parser->tokens.items[parser->index++];
    if (equal(token.kind, "number") || equal(token.kind, "character")) {
        ConditionExpr *result = node("constant");
        result->value = equal(token.kind, "number") ? integer_constant(parser, token.spelling)
                                                    : character_constant(parser, token.spelling);
        return result;
    }
    if (equal(token.kind, "identifier")) {
        ConditionExpr *result = node("identifier");
        result->name = token.spelling;
        return result;
    }
    if (equal(token.spelling, "(")) {
        ConditionExpr *result = expression(parser);
        if (!equal(peek(parser), ")"))
            expression_error(parser, "missing ')' in expression");
        ++parser->index;
        return result;
    }
    expression_error(parser, ml_format("expected value before \"%s\"", token.spelling));
    return NULL;
}
static ConditionExpr *unary(ExpressionParser *parser) {
    if (word_in("+ - ! ~", peek(parser))) {
        const char *op = peek(parser);
        ++parser->index;
        ConditionExpr *result = node("unary");
        result->op = op;
        result->first = unary(parser);
        return result;
    }
    return primary(parser);
}
static ConditionExpr *binary(ExpressionParser *parser, int minimum) {
    ConditionExpr *left = unary(parser);
    while (true) {
        int level = precedence(peek(parser));
        if (!level || level < minimum)
            break;
        const char *op = peek(parser);
        ++parser->index;
        ConditionExpr *right = binary(parser, level + 1);
        ConditionExpr *result = node("binary");
        result->op = op;
        result->first = left;
        result->second = right;
        left = result;
    }
    return left;
}
static ConditionExpr *expression(ExpressionParser *parser) {
    ConditionExpr *first = binary(parser, 1);
    if (equal(peek(parser), "?")) {
        ++parser->index;
        ConditionExpr *second = expression(parser);
        if (!equal(peek(parser), ":"))
            expression_error(parser, "'?' without following ':'");
        ++parser->index;
        ConditionExpr *third = expression(parser);
        ConditionExpr *result = node("conditional");
        result->first = first;
        result->second = second;
        result->third = third;
        return result;
    }
    return first;
}
ConditionExpr *parse_condition(Tokens tokens, const char *directive, char **error) {
    ExpressionParser *parser = ml_alloc(sizeof(*parser));
    parser->tokens = tokens;
    if (setjmp(parser->jump)) {
        *error = parser->error;
        return NULL;
    }
    if (!tokens.count)
        expression_error(parser, ml_format("#%s with no expression", directive));
    ConditionExpr *result = expression(parser);
    if (parser->index < tokens.count)
        expression_error(parser, ml_format("missing binary operator before \"%s\"", peek(parser)));
    *error = NULL;
    return result;
}
bool evaluate_condition(Preprocessor *p, Position position, ConditionExpr *e, int64_t *value,
                        char **error) {
    if (equal(e->kind, "constant")) {
        *value = e->value;
        return true;
    }
    if (equal(e->kind, "identifier")) {
        diagnostic(p, position, "warning", ml_format("identifier \"%s\" evaluates to 0", e->name));
        *value = 0;
        return true;
    }
    int64_t a, b;
    if (!evaluate_condition(p, position, e->first, &a, error))
        return false;
    if (equal(e->kind, "unary")) {
        *value = equal(e->op, "+")   ? a
                 : equal(e->op, "-") ? -a
                 : equal(e->op, "!") ? (a == 0)
                                     : -a - 1;
        return true;
    }
    if (equal(e->kind, "conditional"))
        return evaluate_condition(p, position, a ? e->second : e->third, value, error);
    if (equal(e->op, "&&") && !a) {
        *value = 0;
        return true;
    }
    if (equal(e->op, "||") && a) {
        *value = 1;
        return true;
    }
    if (!evaluate_condition(p, position, e->second, &b, error))
        return false;
    if (equal(e->op, "+"))
        *value = a + b;
    else if (equal(e->op, "-"))
        *value = a - b;
    else if (equal(e->op, "*"))
        *value = a * b;
    else if (equal(e->op, "/") || equal(e->op, "%")) {
        if (!b) {
            *error = "division by zero in #if";
            return false;
        }
        int64_t q = a / b;
        *value = equal(e->op, "/") ? q : a - b * q;
    } else if (equal(e->op, "<<"))
        *value = a * (INT64_C(1) << b);
    else if (equal(e->op, ">>")) {
        int64_t divisor = INT64_C(1) << b, q = a / divisor;
        if (a < 0 && a % divisor)
            --q;
        *value = q;
    } else if (equal(e->op, "&") || equal(e->op, "|") || equal(e->op, "^")) {
        uint32_t left = (uint32_t)a, right = (uint32_t)b;
        uint32_t result = equal(e->op, "&")   ? left & right
                          : equal(e->op, "|") ? left | right
                                              : left ^ right;
        *value = result >= UINT32_C(0x80000000) ? (int64_t)result - INT64_C(4294967296) : result;
    } else if (equal(e->op, "=="))
        *value = a == b;
    else if (equal(e->op, "!="))
        *value = a != b;
    else if (equal(e->op, "<"))
        *value = a < b;
    else if (equal(e->op, ">"))
        *value = a > b;
    else if (equal(e->op, "<="))
        *value = a <= b;
    else if (equal(e->op, ">="))
        *value = a >= b;
    else
        *value = b != 0;
    return true;
}

#include "preprocessor.h"
const char *directive_name(Tokens tokens) {
    return tokens.count >= 2 && equal(tokens.items[0].spelling, "#") &&
                   equal(tokens.items[1].kind, "identifier")
               ? tokens.items[1].spelling
               : "";
}
static char *detect_guard(LogicalLines logical) {
    TokenGroups lines = {0};
    for (int i = 0; i < logical.count; ++i)
        if (logical.items[i].tokens.count)
            PUSH(lines, logical.items[i].tokens);
    if (!lines.count)
        return "";
    Tokens first = lines.items[0], last = lines.items[lines.count - 1];
    if (first.count != 3 || !equal(first.items[0].spelling, "#") ||
        !equal(first.items[1].spelling, "ifndef") || !equal(first.items[1].kind, "identifier") ||
        !equal(first.items[2].kind, "identifier") || last.count != 2 ||
        !equal(last.items[0].spelling, "#") || !equal(last.items[1].spelling, "endif") ||
        !equal(last.items[1].kind, "identifier"))
        return "";
    int depth = 0;
    for (int i = 0; i < lines.count; ++i) {
        const char *name = directive_name(lines.items[i]);
        if (word_in("elif elifdef elifndef else", name) && depth == 1)
            return "";
        if (word_in("if ifdef ifndef", name))
            ++depth;
        else if (equal(name, "endif"))
            --depth;
        if (depth == 0 && i + 1 < lines.count)
            return "";
    }
    return depth == 0 ? (char *)first.items[2].spelling : "";
}
char *search_include(const char *name, bool quoted) {
    char *paths[2] = {(char *)name, ml_format("include/%s", name)};
    for (int i = quoted ? 0 : 1; i < 2; ++i) {
        struct stat info;
        if (stat(ml_format("input/%s", paths[i]), &info) == 0 && S_ISREG(info.st_mode))
            return paths[i];
    }
    return "";
}
FileData *find_file(IncludeManager *manager, const char *path) {
    for (int i = 0; i < manager->files.count; ++i)
        if (equal(manager->files.items[i]->path, path))
            return manager->files.items[i];
    return NULL;
}
FileData *load_file(IncludeManager *manager, const char *path) {
    FileData *file = find_file(manager, path);
    if (file)
        return file;
    FILE *input = fopen(ml_format("input/%s", path), "r");
    Text source = {0};
    int c;
    if (input) {
        while ((c = fgetc(input)) != EOF)
            text_char(&source, (char)c);
        fclose(input);
    }
    file = ml_alloc(sizeof(*file));
    file->path = path;
    file->lines = lex_source(text_value(&source));
    for (int i = 0; i < source.count; ++i)
        if (source.items[i] == '\n')
            ++file->physical_lines;
    file->guard = detect_guard(file->lines);
    PUSH(manager->files, file);
    return file;
}

#include "preprocessor.h"
bool equal(const char *left, const char *right) {
    return left && right && strcmp(left, right) == 0;
}
bool word_in(const char *words, const char *word) {
    if (!word)
        return false;
    size_t n = strlen(word);
    for (const char *p = words; *p;) {
        const char *end = strchr(p, ' ');
        if (!end)
            end = p + strlen(p);
        if ((size_t)(end - p) == n && strncmp(p, word, n) == 0)
            return true;
        p = *end ? end + 1 : end;
    }
    return false;
}
bool string_member(StringList list, const char *name) {
    for (int i = 0; i < list.count; ++i)
        if (equal(list.items[i], name))
            return true;
    return false;
}
void string_insert(StringList *list, const char *name) {
    if (!string_member(*list, name))
        PUSH(*list, (char *)name);
}
StringList names_union(StringList left, StringList right) {
    StringList result = {0};
    for (int i = 0; i < left.count; ++i)
        string_insert(&result, left.items[i]);
    for (int i = 0; i < right.count; ++i)
        string_insert(&result, right.items[i]);
    return result;
}
StringList names_intersection(StringList left, StringList right) {
    StringList result = {0};
    for (int i = 0; i < left.count; ++i)
        if (string_member(right, left.items[i]))
            string_insert(&result, left.items[i]);
    return result;
}
static bool identifier_start(char c) {
    return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}
static bool digit(char c) { return c >= '0' && c <= '9'; }
static ReadToken read_token_length(const char *source, size_t n, size_t index, bool header) {
    char c = source[index];
    if (header && c == '<') {
        const char *end = strchr(source + index + 1, '>');
        const char *newline = strchr(source + index + 1, '\n');
        if (end && (!newline || end < newline))
            return (ReadToken){"header",
                               ml_text(source + index, (size_t)(end - source) + 1 - index),
                               (size_t)(end - source) + 1};
    }
    if (identifier_start(c)) {
        size_t end = index + 1;
        while (end < n && (identifier_start(source[end]) || digit(source[end])))
            ++end;
        return (ReadToken){"identifier", ml_text(source + index, end - index), end};
    }
    if (digit(c) || (c == '.' && index + 1 < n && digit(source[index + 1]))) {
        size_t end = index + 1;
        while (end < n) {
            if (strchr("eEpP", source[end]) && end + 1 < n &&
                (source[end + 1] == '+' || source[end + 1] == '-'))
                end += 2;
            else if (identifier_start(source[end]) || digit(source[end]) || source[end] == '.')
                ++end;
            else
                break;
        }
        return (ReadToken){"number", ml_text(source + index, end - index), end};
    }
    if (c == '\'' || c == '"') {
        size_t end = index + 1;
        while (end < n && source[end] != '\n') {
            if (source[end] == c)
                return (ReadToken){c == '\'' ? "character" : "string",
                                   ml_text(source + index, end + 1 - index), end + 1};
            if (source[end] == '\\' && end + 1 < n && source[end + 1] != '\n')
                end += 2;
            else
                ++end;
        }
    }
    const char *punctuators[] = {
        "...", "<<=", ">>=", "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=",
        "&&",  "||",  "*=",  "/=", "%=", "+=", "-=", "&=", "^=", "|=", "##", "[",
        "]",   "(",   ")",   "{",  "}",  ".",  "&",  "*",  "+",  "-",  "~",  "!",
        "/",   "%",   "<",   ">",  "^",  "|",  "?",  ":",  ";",  "=",  ",",  "#"};
    for (size_t i = 0; i < sizeof(punctuators) / sizeof(*punctuators); ++i)
        if (strncmp(source + index, punctuators[i], strlen(punctuators[i])) == 0)
            return (ReadToken){"punctuator", (char *)punctuators[i],
                               index + strlen(punctuators[i])};
    return (ReadToken){"other", ml_text(source + index, 1), index + 1};
}
ReadToken read_token(const char *source, size_t index, bool header) {
    return read_token_length(source, strlen(source), index, header);
}
static LogicalLines scan(const char *source, const int *positions, int start) {
    LogicalLines result = {0};
    Tokens tokens = {0};
    bool spaced = true;
    size_t index = 0, n = strlen(source);
    while (index < n) {
        if (source[index] == ' ') {
            spaced = true;
            ++index;
        } else if (source[index] == '\n') {
            int end = positions[index++];
            LogicalLine line = {tokens, start, end};
            PUSH(result, line);
            tokens = (Tokens){0};
            start = end + 1;
            spaced = true;
        } else if (strncmp(source + index, "/*", 2) == 0) {
            const char *end = strstr(source + index + 2, "*/");
            index = end ? (size_t)(end - source) + 2 : n;
            spaced = true;
        } else if (strncmp(source + index, "//", 2) == 0) {
            const char *end = strchr(source + index, '\n');
            index = end ? (size_t)(end - source) : n;
            spaced = true;
        } else {
            bool header = tokens.count == 2 && equal(tokens.items[0].spelling, "#") &&
                          equal(tokens.items[1].spelling, "include");
            ReadToken read = read_token_length(source, n, index, header);
            Token token = {read.kind, read.spelling, positions[index], spaced, {0}};
            PUSH(tokens, token);
            index = read.end;
            spaced = false;
        }
    }
    if (tokens.count) {
        LogicalLine line = {tokens, start, positions[n - 1]};
        PUSH(result, line);
    }
    return result;
}
LogicalLines lex_source(const char *source) {
    size_t n = strlen(source);
    Text characters = {0};
    int *positions = ml_alloc((n + 1) * sizeof(*positions));
    int line = 1, count = 0;
    for (size_t i = 0; i < n;) {
        if (i + 1 < n && source[i] == '\\' && source[i + 1] == '\n') {
            i += 2;
            ++line;
            continue;
        }
        char c = source[i++];
        text_char(&characters, c);
        positions[count++] = line;
        if (c == '\n')
            ++line;
    }
    return scan(text_value(&characters), positions, 1);
}
Tokens lex_definition(const char *text, int line) {
    char *source = ml_format("%s\n", text);
    size_t n = strlen(source);
    int *positions = ml_alloc(n * sizeof(*positions));
    for (size_t i = 0; i < n; ++i)
        positions[i] = line;
    LogicalLines lines = scan(source, positions, line);
    Tokens result = {0};
    for (int i = 0; i < lines.count; ++i)
        for (int j = 0; j < lines.items[i].tokens.count; ++j)
            PUSH(result, lines.items[i].tokens.items[j]);
    return result;
}
Tokens copy_tokens(Tokens tokens) {
    Tokens result = {0};
    for (int i = 0; i < tokens.count; ++i)
        PUSH(result, tokens.items[i]);
    return result;
}
char *render(Tokens tokens) {
    Text result = {0};
    for (int i = 0; i < tokens.count; ++i) {
        if (i && tokens.items[i].space)
            text_char(&result, ' ');
        text_add(&result, tokens.items[i].spelling);
    }
    return text_value(&result);
}
const char *single_token(const char *source) {
    if (!*source || strncmp(source, "//", 2) == 0 || strncmp(source, "/*", 2) == 0)
        return NULL;
    ReadToken token = read_token(source, 0, false);
    return token.end == strlen(source) ? token.kind : NULL;
}

#include "preprocessor.h"
typedef struct Allocation {
    void *value;
    struct Allocation *next;
} Allocation;
static Allocation *allocations;
void *ml_alloc(size_t size) {
    void *value = calloc(1, size ? size : 1);
    Allocation *record = malloc(sizeof(*record));
    if (!value || !record)
        exit(1);
    record->value = value;
    record->next = allocations;
    allocations = record;
    return value;
}
void *ml_grow(void *items, int *capacity, size_t size, int count) {
    int next = *capacity ? *capacity * 2 : 8;
    void *result = ml_alloc((size_t)next * size);
    if (count)
        memcpy(result, items, (size_t)count * size);
    *capacity = next;
    return result;
}
char *ml_text(const char *text, size_t length) {
    char *result = ml_alloc(length + 1);
    memcpy(result, text, length);
    return result;
}
char *ml_format(const char *format, ...) {
    va_list args, copy;
    va_start(args, format);
    va_copy(copy, args);
    int count = vsnprintf(NULL, 0, format, copy);
    va_end(copy);
    char *result = ml_alloc((size_t)count + 1);
    vsnprintf(result, (size_t)count + 1, format, args);
    va_end(args);
    return result;
}
void ml_cleanup(void) {
    while (allocations) {
        Allocation *next = allocations->next;
        free(allocations->value);
        free(allocations);
        allocations = next;
    }
}
void text_add(Text *text, const char *value) {
    size_t length = strlen(value);
    while ((size_t)text->capacity < (size_t)text->count + length + 1)
        text->items = ml_grow(text->items, &text->capacity, 1, text->count);
    memcpy(text->items + text->count, value, length + 1);
    text->count += (int)length;
}
void text_char(Text *text, char c) {
    char value[2] = {c, 0};
    text_add(text, value);
}
char *text_value(Text *text) {
    if (!text->items)
        return ml_text("", 0);
    return text->items;
}
Position display_position(Inclusion *inclusion, int physical) {
    return (Position){inclusion->display_file, physical + inclusion->offset};
}
bool skipping(Inclusion *inclusion) {
    return inclusion->stack.count && !inclusion->stack.items[inclusion->stack.count - 1]->active;
}
Macro *find_macro(Preprocessor *p, const char *name) {
    for (MacroEntry *entry = p->macros; entry; entry = entry->next)
        if (equal(entry->name, name))
            return entry->macro;
    return NULL;
}
void set_macro(Preprocessor *p, const char *name, Macro *macro) {
    for (MacroEntry *entry = p->macros; entry; entry = entry->next)
        if (equal(entry->name, name)) {
            entry->macro = macro;
            return;
        }
    MacroEntry *entry = ml_alloc(sizeof(*entry));
    entry->name = name;
    entry->macro = macro;
    entry->next = p->macros;
    p->macros = entry;
}
void diagnostic(Preprocessor *p, Position position, const char *kind, const char *message) {
    char *line = ml_format("%s: %s: %s", position_text(position), kind, message);
    PUSH(p->diagnostics, line);
    if (equal(kind, "error"))
        ++p->errors;
    else
        ++p->warnings;
}
static void event(Preprocessor *p, Position position, const char *content) {
    char *line = ml_format("%s: %s", position_text(position), content);
    PUSH(p->history, line);
}
Header read_header(Tokens tokens, int index) {
    Header result = {0};
    if (index >= tokens.count)
        return result;
    Token token = tokens.items[index];
    if (equal(token.kind, "string") || equal(token.kind, "header")) {
        result.present = true;
        result.rendering = (char *)token.spelling;
        result.name = ml_text(token.spelling + 1, strlen(token.spelling) - 2);
        result.quoted = token.spelling[0] == '"';
        result.next = index + 1;
    } else if (equal(token.spelling, "<")) {
        int end = index + 1;
        while (end < tokens.count && !equal(tokens.items[end].spelling, ">"))
            ++end;
        if (end == tokens.count) {
            result.error = "missing terminating > character";
            return result;
        }
        Tokens middle = {tokens.items + index + 1, end - index - 1, 0};
        result.present = true;
        result.name = render(middle);
        result.rendering = ml_format("<%s>", result.name);
        result.next = end + 1;
    }
    return result;
}
static bool separator_needed(const char *left, const char *right) {
    if (equal(left, "/") && (right[0] == '/' || right[0] == '*'))
        return true;
    char *joined = ml_format("%s%s", left, right);
    return read_token(joined, 0, false).end != strlen(left);
}
static char *output_render(Tokens tokens) {
    Text result = {0};
    for (int i = 0; i < tokens.count; ++i) {
        if (i && (tokens.items[i].space ||
                  separator_needed(tokens.items[i - 1].spelling, tokens.items[i].spelling)))
            text_char(&result, ' ');
        text_add(&result, tokens.items[i].spelling);
    }
    return text_value(&result);
}
static bool decimal_token(Token token) {
    if (!equal(token.kind, "number") || !*token.spelling)
        return false;
    for (const char *c = token.spelling; *c; ++c)
        if (*c < '0' || *c > '9')
            return false;
    return true;
}
static void poison_check(Preprocessor *p, Inclusion *inclusion, Tokens tokens) {
    for (int i = 0; i < tokens.count; ++i) {
        Token token = tokens.items[i];
        if (equal(token.kind, "identifier") && string_member(p->poisoned, token.spelling))
            diagnostic(p, display_position(inclusion, token.line), "error",
                       ml_format("attempt to use poisoned \"%s\"", token.spelling));
    }
}
static void unused_check(Preprocessor *p, Macro *macro) {
    if (macro->main_file && !macro->expanded && !macro->tested)
        diagnostic(p, macro->position, "warning",
                   ml_format("macro \"%s\" is not used", macro->name));
}
static void define(Preprocessor *p, Tokens tokens, Position position, bool main_file) {
    char *error = NULL;
    Macro *macro = parse_definition(tokens, position, main_file, &error);
    if (error) {
        diagnostic(p, position, "error", error);
        return;
    }
    Macro *previous = find_macro(p, macro->name);
    const char *operation = "define";
    if (!previous) {
        set_macro(p, macro->name, macro);
        string_insert(&p->ever_defined, macro->name);
    } else if (identical(previous, macro))
        operation = "identical";
    else {
        unused_check(p, previous);
        diagnostic(p, position, "warning",
                   ml_format("\"%s\" redefined (previous definition at %s)", macro->name,
                             position_text(previous->position)));
        set_macro(p, macro->name, macro);
        string_insert(&p->ever_defined, macro->name);
        operation = "redefine";
    }
    event(p, position, ml_format("%s %s", operation, signature(macro)));
}
static void undefine(Preprocessor *p, Tokens tokens, Position position) {
    char *error = check_name(tokens, "undef");
    if (error) {
        diagnostic(p, position, "error", error);
        return;
    }
    if (tokens.count > 1)
        diagnostic(p, position, "warning", "extra tokens at end of #undef directive");
    const char *name = tokens.items[0].spelling;
    Macro *previous = find_macro(p, name);
    if (previous) {
        unused_check(p, previous);
        set_macro(p, name, NULL);
        event(p, position, ml_format("undef %s", name));
    } else
        event(p, position, ml_format("undef %s (not defined)", name));
}
static StringList read_lines(const char *path) {
    StringList result = {0};
    FILE *input = fopen(path, "r");
    if (!input)
        return result;
    Text line = {0};
    int c;
    while ((c = fgetc(input)) != EOF) {
        if (c == '\n') {
            char *value = text_value(&line);
            PUSH(result, value);
            line = (Text){0};
        } else
            text_char(&line, (char)c);
    }
    fclose(input);
    return result;
}
static void process_defines(Preprocessor *p) {
    StringList lines = read_lines("input/defines.txt");
    for (int i = 0; i < lines.count; ++i) {
        const char *line = lines.items[i];
        if (!*line)
            continue;
        const char *at = strchr(line, '=');
        char *text = at ? ml_format("%s %s", ml_text(line, (size_t)(at - line)), at + 1)
                        : ml_format("%s 1", line);
        define(p, lex_definition(text, i + 1), (Position){"defines.txt", i + 1}, false);
    }
}
static void marker(Preprocessor *p, const char *file, int line, int flag) {
    char *text =
        flag ? ml_format("# %d \"%s\" %d", line, file, flag) : ml_format("# %d \"%s\"", line, file);
    PUSH(p->output, text);
    p->previous = (Position){file, line - 1};
}
static void output_line(Preprocessor *p, Inclusion *inclusion, int physical, const char *text) {
    Position position = display_position(inclusion, physical);
    if (equal(position.file, p->previous.file) && p->previous.line < position.line &&
        (int64_t)position.line <= (int64_t)p->previous.line + 8) {
        for (int64_t i = (int64_t)p->previous.line + 1; i < position.line; ++i)
            PUSH(p->output, "");
    } else
        marker(p, position.file, position.line, 0);
    PUSH(p->output, (char *)text);
    p->previous = position;
    ++inclusion->source->output_lines;
}
static void flush(Preprocessor *p, Inclusion *inclusion) {
    Tokens segment = inclusion->segment;
    inclusion->segment = (Tokens){0};
    if (!segment.count)
        return;
    poison_check(p, inclusion, segment);
    Tokens expanded = expand(p, inclusion, segment);
    for (int start = 0; start < expanded.count;) {
        int end = start + 1;
        while (end < expanded.count && expanded.items[end].line == expanded.items[start].line)
            ++end;
        Tokens part = {expanded.items + start, end - start, 0};
        output_line(p, inclusion, expanded.items[start].line, output_render(part));
        start = end;
    }
}
static bool macro_defined(Preprocessor *p, const char *name) {
    Macro *macro = find_macro(p, name);
    if (macro) {
        ++macro->tested;
        return true;
    }
    return builtin(name) || equal(name, "__has_include");
}
static Tokens replace_operators(Preprocessor *p, Tokens operands, char **error) {
    Tokens result = {0};
    *error = NULL;
    for (int position = 0; position < operands.count;) {
        Token token = operands.items[position];
        int index = position + 1;
        bool value = false;
        if (equal(token.kind, "identifier") && equal(token.spelling, "defined")) {
            bool parenthesized =
                index < operands.count && equal(operands.items[index].spelling, "(");
            if (parenthesized)
                ++index;
            if (index == operands.count || !equal(operands.items[index].kind, "identifier")) {
                *error = "operator \"defined\" requires an identifier";
                return result;
            }
            const char *name = operands.items[index++].spelling;
            if (parenthesized) {
                if (index == operands.count || !equal(operands.items[index].spelling, ")")) {
                    *error = "missing ')' after \"defined\"";
                    return result;
                }
                ++index;
            }
            value = macro_defined(p, name);
        } else if (equal(token.kind, "identifier") && equal(token.spelling, "__has_include")) {
            if (index == operands.count || !equal(operands.items[index].spelling, "(")) {
                *error = "missing '(' after \"__has_include\"";
                return result;
            }
            Header header = read_header(operands, index + 1);
            if (header.error) {
                *error = header.error;
                return result;
            }
            if (!header.present || !*header.name) {
                *error = "operator \"__has_include\" requires a header-name";
                return result;
            }
            index = header.next;
            if (index == operands.count || !equal(operands.items[index].spelling, ")")) {
                *error = "missing ')' after \"__has_include\" operand";
                return result;
            }
            ++index;
            value = *search_include(header.name, header.quoted) != 0;
        } else {
            PUSH(result, token);
            ++position;
            continue;
        }
        Token replacement = {"number", value ? "1" : "0", token.line, token.space, {0}};
        PUSH(result, replacement);
        position = index;
    }
    return result;
}
typedef struct {
    bool valid;
    int64_t value;
    Tokens expanded;
    bool was_expanded;
} TestResult;
static TestResult test(Preprocessor *p, Inclusion *inclusion, LogicalLine line, const char *name,
                       Tokens operands) {
    Position position = display_position(inclusion, line.tokens.items[0].line);
    poison_check(p, inclusion, operands);
    TestResult result = {0};
    if (!equal(name, "if") && !equal(name, "elif")) {
        if (!operands.count) {
            diagnostic(p, position, "error",
                       ml_format("no macro name given in #%s directive", name));
            return result;
        }
        if (!equal(operands.items[0].kind, "identifier")) {
            diagnostic(p, position, "error", "macro names must be identifiers");
            return result;
        }
        if (operands.count > 1)
            diagnostic(p, position, "warning",
                       ml_format("extra tokens at end of #%s directive", name));
        bool defined = macro_defined(p, operands.items[0].spelling);
        if (equal(name, "ifndef") || equal(name, "elifndef"))
            defined = !defined;
        result.valid = true;
        result.value = defined;
        return result;
    }
    char *error = NULL;
    Tokens replaced = replace_operators(p, operands, &error);
    if (error) {
        diagnostic(p, position, "error", error);
        return result;
    }
    result.expanded = expand(p, inclusion, replaced);
    result.was_expanded = true;
    ConditionExpr *expression = parse_condition(result.expanded, name, &error);
    if (!error) {
        int64_t value = 0;
        if (evaluate_condition(p, position, expression, &value, &error)) {
            result.valid = true;
            result.value = value;
        }
    }
    if (error)
        diagnostic(p, position, "error", error);
    return result;
}
static char *test_description(const char *name, TestResult tested) {
    char *result = "not taken (error)";
    if (tested.valid) {
        result = tested.value ? "taken" : "not taken";
        if (equal(name, "if") || equal(name, "elif"))
            result = ml_format("%s (value %lld)", result, (long long)tested.value);
    }
    if (tested.was_expanded)
        result = ml_format("%s [%s]", result, output_render(tested.expanded));
    return result;
}
static void close_region(Preprocessor *p, Inclusion *inclusion, ConditionalBlock *block, int end) {
    int start = block->skip_start;
    if (start && end >= start) {
        Position first = display_position(inclusion, start),
                 last = display_position(inclusion, end);
        char *line =
            ml_format("%s:%d-%d lines=%d", first.file, first.line, last.line, end - start + 1);
        PUSH(p->regions, line);
        inclusion->source->skipped_lines += end - start + 1;
    }
    block->skip_start = 0;
}
static void conditional_record(Preprocessor *p, Position position, int depth, const char *name,
                               Tokens operands, const char *description) {
    char *directive =
        operands.count ? ml_format("#%s %s", name, render(operands)) : ml_format("#%s", name);
    char *indentation = ml_alloc((size_t)2 * depth + 1);
    memset(indentation, ' ', (size_t)2 * depth);
    char *record =
        ml_format("%s: %s%s => %s", position_text(position), indentation, directive, description);
    PUSH(p->conditionals, record);
    const char *prefixes[] = {"taken", "not taken", "skipped", "not evaluated", "closes"};
    for (int i = 0; i < 5; ++i)
        if (strncmp(description, prefixes[i], strlen(prefixes[i])) == 0) {
            ++p->condition_counts[i];
            break;
        }
}
static void conditional(Preprocessor *p, Inclusion *inclusion, LogicalLine line, const char *name,
                        Tokens operands) {
    Position position = display_position(inclusion, line.tokens.items[0].line);
    if (word_in("if ifdef ifndef", name)) {
        ConditionalBlock *block = ml_alloc(sizeof(*block));
        block->kind = name;
        block->start = position;
        block->parent = !skipping(inclusion);
        char *description = "skipped";
        if (block->parent) {
            TestResult tested = test(p, inclusion, line, name, operands);
            if (tested.valid && tested.value)
                block->chosen = block->active = true;
            else
                block->skip_start = line.end + 1;
            description = test_description(name, tested);
        }
        conditional_record(p, position, inclusion->stack.count, name, operands, description);
        PUSH(inclusion->stack, block);
        return;
    }
    if (!inclusion->stack.count) {
        diagnostic(p, position, "error", ml_format("#%s without #if", name));
        return;
    }
    int depth = inclusion->stack.count - 1;
    ConditionalBlock *block = inclusion->stack.items[depth];
    close_region(p, inclusion, block, line.start - 1);
    char *description = NULL;
    if (equal(name, "endif")) {
        --inclusion->stack.count;
        if (block->parent && operands.count)
            diagnostic(p, position, "warning", "extra tokens at end of #endif directive");
        description = ml_format("closes #%s at line %d", block->kind, block->start.line);
    } else {
        if (block->else_seen)
            diagnostic(p, position, "error", ml_format("#%s after #else", name));
        if (equal(name, "else")) {
            if (block->parent && operands.count)
                diagnostic(p, position, "warning", "extra tokens at end of #else directive");
            block->else_seen = true;
            if (block->parent) {
                block->active = !block->chosen;
                block->chosen = true;
                description = block->active ? "taken" : "not taken";
            } else {
                block->active = false;
                description = "skipped";
            }
        } else if (!block->parent) {
            block->active = false;
            description = "skipped";
        } else if (block->chosen) {
            block->active = false;
            description = "not evaluated";
        } else {
            TestResult tested = test(p, inclusion, line, name, operands);
            block->active = tested.valid && tested.value;
            if (block->active)
                block->chosen = true;
            description = test_description(name, tested);
        }
        if (block->parent && !block->active)
            block->skip_start = line.end + 1;
    }
    conditional_record(p, position, depth, name, operands, description);
}
static void process_file(Preprocessor *, const char *, int);
static void include(Preprocessor *p, Inclusion *inclusion, LogicalLine line, Tokens operands) {
    Position position = display_position(inclusion, line.tokens.items[0].line);
    Header header = read_header(operands, 0);
    if (header.error) {
        diagnostic(p, position, "error", header.error);
        return;
    }
    if (!header.present && operands.count) {
        operands = expand(p, inclusion, operands);
        header = read_header(operands, 0);
        if (header.error) {
            diagnostic(p, position, "error", header.error);
            return;
        }
    }
    if (!header.present) {
        diagnostic(p, position, "error", "#include expects \"FILENAME\" or <FILENAME>");
        return;
    }
    if (header.next < operands.count)
        diagnostic(p, position, "warning", "extra tokens at end of #include directive");
    if (!*header.name) {
        diagnostic(p, position, "error", "empty filename in #include");
        return;
    }
    char *indentation = ml_alloc((size_t)2 * (inclusion->depth + 1) + 1);
    memset(indentation, ' ', (size_t)2 * (inclusion->depth + 1));
    char *prefix = ml_format("%s%d: ", indentation, line.tokens.items[0].line);
    char *path = search_include(header.name, header.quoted);
    char *tree_line;
    if (!*path) {
        tree_line = ml_format("%s%s [not found]", prefix, header.rendering);
        PUSH(p->tree, tree_line);
        diagnostic(p, position, "error",
                   ml_format("cannot find include file %s", header.rendering));
        return;
    }
    FileData *previous = find_file(&p->manager, path);
    if (previous && previous->once) {
        tree_line = ml_format("%s%s [skipped: pragma once]", prefix, path);
        PUSH(p->tree, tree_line);
        ++previous->skipped;
        return;
    }
    if (previous && *previous->guard && find_macro(p, previous->guard)) {
        tree_line = ml_format("%s%s [skipped: guard %s]", prefix, path, previous->guard);
        PUSH(p->tree, tree_line);
        ++previous->skipped;
        return;
    }
    if (inclusion->depth + 1 > 8) {
        tree_line = ml_format("%s%s [too deep]", prefix, path);
        PUSH(p->tree, tree_line);
        diagnostic(p, position, "error", "#include nested too deeply");
        return;
    }
    tree_line = ml_format("%s%s", prefix, path);
    PUSH(p->tree, tree_line);
    marker(p, path, 1, 1);
    process_file(p, path, inclusion->depth + 1);
    Position next = display_position(inclusion, line.end + 1);
    marker(p, next.file, next.line, 2);
}
static void line_directive(Preprocessor *p, Inclusion *inclusion, LogicalLine line,
                           Tokens operands) {
    Position position = display_position(inclusion, line.tokens.items[0].line);
    if (!operands.count || !decimal_token(operands.items[0]))
        operands = expand(p, inclusion, operands);
    if (!operands.count || operands.count > 2 || !decimal_token(operands.items[0]) ||
        (operands.count == 2 && !equal(operands.items[1].kind, "string"))) {
        diagnostic(p, position, "error", "invalid #line directive");
        return;
    }
    int64_t number = strtoll(operands.items[0].spelling, NULL, 10);
    if (number < 1 || number > 2147483647LL) {
        diagnostic(p, position, "error", "line number out of range");
        return;
    }
    inclusion->offset = (int)number - (line.end + 1);
    if (operands.count == 2)
        inclusion->display_file =
            ml_text(operands.items[1].spelling + 1, strlen(operands.items[1].spelling) - 2);
}
static void macro_pragma(Preprocessor *p, Position position, Tokens operands,
                         const char *operation) {
    if (operands.count != 4 || !equal(operands.items[1].spelling, "(") ||
        !equal(operands.items[2].kind, "string") || !equal(operands.items[3].spelling, ")")) {
        diagnostic(p, position, "error", ml_format("invalid #pragma %s directive", operation));
        return;
    }
    char *name = ml_text(operands.items[2].spelling + 1, strlen(operands.items[2].spelling) - 2);
    Saved *saved = p->saved;
    while (saved && !equal(saved->name, name))
        saved = saved->next;
    if (!saved) {
        saved = ml_alloc(sizeof(*saved));
        saved->name = name;
        saved->next = p->saved;
        p->saved = saved;
    }
    if (equal(operation, "push_macro")) {
        Macro *macro = find_macro(p, name);
        PUSH(saved->stack, macro);
        event(p, position, ml_format("push %s", name));
        return;
    }
    if (!saved->stack.count) {
        diagnostic(p, position, "warning", ml_format("no matching push_macro for \"%s\"", name));
        return;
    }
    Macro *macro = saved->stack.items[--saved->stack.count];
    set_macro(p, name, macro);
    event(p, position, macro ? ml_format("pop %s", name) : ml_format("pop %s (undefined)", name));
}
static void pragma(Preprocessor *p, Inclusion *inclusion, LogicalLine line, Tokens operands) {
    Position position = display_position(inclusion, line.tokens.items[0].line);
    const char *name = operands.count && equal(operands.items[0].kind, "identifier")
                           ? operands.items[0].spelling
                           : "";
    if (equal(name, "once")) {
        if (operands.count > 1)
            diagnostic(p, position, "warning", "extra tokens at end of #pragma once directive");
        if (inclusion->depth == 0)
            diagnostic(p, position, "warning", "#pragma once in main file");
        inclusion->source->once = true;
    } else if (operands.count >= 2 && equal(operands.items[0].spelling, "GCC") &&
               equal(operands.items[1].spelling, "poison")) {
        for (int i = 2; i < operands.count; ++i)
            if (!equal(operands.items[i].kind, "identifier")) {
                diagnostic(p, position, "error", "invalid #pragma GCC poison directive");
                return;
            }
        for (int i = 2; i < operands.count; ++i) {
            const char *name = operands.items[i].spelling;
            if (find_macro(p, name))
                diagnostic(p, position, "warning",
                           ml_format("poisoning existing macro \"%s\"", name));
            string_insert(&p->poisoned, name);
        }
    } else if (equal(name, "push_macro") || equal(name, "pop_macro"))
        macro_pragma(p, position, operands, name);
    else
        output_line(p, inclusion, line.tokens.items[0].line,
                    operands.count ? ml_format("#pragma %s", render(operands)) : "#pragma");
}
static void directive(Preprocessor *p, Inclusion *inclusion, LogicalLine line, const char *name,
                      Tokens operands) {
    if (line.tokens.count == 1)
        return;
    bool poisoning = equal(name, "pragma") && operands.count >= 2 &&
                     equal(operands.items[0].spelling, "GCC") &&
                     equal(operands.items[1].spelling, "poison");
    if (!poisoning)
        poison_check(p, inclusion, operands);
    Position position = display_position(inclusion, line.tokens.items[0].line);
    if (equal(name, "define"))
        define(p, operands, position, inclusion->depth == 0);
    else if (equal(name, "undef"))
        undefine(p, operands, position);
    else if (equal(name, "include"))
        include(p, inclusion, line, operands);
    else if (equal(name, "line"))
        line_directive(p, inclusion, line, operands);
    else if (equal(name, "error") || equal(name, "warning"))
        diagnostic(p, position, name,
                   operands.count ? ml_format("#%s %s", name, render(operands))
                                  : ml_format("#%s", name));
    else if (equal(name, "pragma"))
        pragma(p, inclusion, line, operands);
    else
        diagnostic(p, position, "error",
                   ml_format("invalid preprocessing directive #%s", line.tokens.items[1].spelling));
}
static void process_file(Preprocessor *p, const char *path, int depth) {
    FileData *source = load_file(&p->manager, path);
    ++source->entered;
    Inclusion inclusion = {0};
    inclusion.source = source;
    inclusion.depth = depth;
    inclusion.display_file = path;
    for (int i = 0; i < source->lines.count; ++i) {
        LogicalLine line = source->lines.items[i];
        bool is_directive = line.tokens.count && equal(line.tokens.items[0].spelling, "#");
        const char *name = directive_name(line.tokens);
        Tokens operands = {0};
        if (line.tokens.count > 2)
            operands = (Tokens){line.tokens.items + 2, line.tokens.count - 2, 0};
        if (is_directive && word_in("if ifdef ifndef elif elifdef elifndef else endif", name)) {
            flush(p, &inclusion);
            conditional(p, &inclusion, line, name, operands);
        } else if (skipping(&inclusion))
            continue;
        else if (is_directive) {
            flush(p, &inclusion);
            directive(p, &inclusion, line, name, operands);
        } else
            for (int j = 0; j < line.tokens.count; ++j)
                PUSH(inclusion.segment, line.tokens.items[j]);
    }
    flush(p, &inclusion);
    for (int i = 0; i < inclusion.stack.count; ++i)
        close_region(p, &inclusion, inclusion.stack.items[i], source->physical_lines);
    for (int i = 0; i < inclusion.stack.count; ++i) {
        ConditionalBlock *block = inclusion.stack.items[i];
        diagnostic(p, block->start, "error", ml_format("unterminated #%s", block->kind));
    }
}
static int string_compare(const void *left, const void *right) {
    return strcmp(*(char *const *)left, *(char *const *)right);
}
static int macro_compare(const void *left, const void *right) {
    Macro *a = *(Macro *const *)left;
    Macro *b = *(Macro *const *)right;
    return strcmp(a->name, b->name);
}
static int file_compare(const void *left, const void *right) {
    FileData *a = *(FileData *const *)left;
    FileData *b = *(FileData *const *)right;
    return strcmp(a->path, b->path);
}
static MacroList sorted_macros(Preprocessor *p) {
    MacroList result = {0};
    for (MacroEntry *entry = p->macros; entry; entry = entry->next)
        if (entry->macro)
            PUSH(result, entry->macro);
    if (result.count > 1)
        qsort(result.items, (size_t)result.count, sizeof(Macro *), macro_compare);
    return result;
}
static bool macro_member(MacroList list, Macro *macro) {
    for (int i = 0; i < list.count; ++i)
        if (list.items[i] == macro)
            return true;
    return false;
}
static bool recursive_visit(Preprocessor *p, Macro *current, Macro *target, MacroList *seen) {
    PUSH(*seen, current);
    for (int i = 0; i < current->references.count; ++i) {
        Macro *next = find_macro(p, current->references.items[i]);
        if (next == target)
            return true;
        if (!macro_member(*seen, next) && recursive_visit(p, next, target, seen))
            return true;
    }
    return false;
}
static void write_lines(const char *name, StringList lines) {
    FILE *output = fopen(ml_format("output/%s", name), "w");
    if (!output)
        return;
    for (int i = 0; i < lines.count; ++i) {
        size_t n = strlen(lines.items[i]);
        while (n && lines.items[i][n - 1] == ' ')
            --n;
        fwrite(lines.items[i], 1, n, output);
        fputc('\n', output);
    }
    fclose(output);
}
static void write_reports(Preprocessor *p) {
    StringList includes = {0};
    for (int i = 0; i < p->tree.count; ++i)
        PUSH(includes, p->tree.items[i]);
    PUSH(includes, "");
    PUSH(includes, "== files ==");
    FileList ordered = {0};
    for (int i = 0; i < p->manager.files.count; ++i)
        PUSH(ordered, p->manager.files.items[i]);
    if (ordered.count > 1)
        qsort(ordered.items, (size_t)ordered.count, sizeof(FileData *), file_compare);
    for (int i = 0; i < ordered.count; ++i) {
        FileData *file = ordered.items[i];
        char *line = ml_format(
            "%s entered=%d skipped=%d lines=%d output_lines=%d skipped_lines=%d guard=%s once=%s",
            file->path, file->entered, file->skipped, file->physical_lines, file->output_lines,
            file->skipped_lines, *file->guard ? file->guard : "-", file->once ? "yes" : "no");
        PUSH(includes, line);
    }
    PUSH(includes, "");
    char *current = "main.o:";
    bool has_path = false;
    for (int i = 0; i < p->manager.files.count; ++i) {
        const char *path = p->manager.files.items[i]->path;
        if (strlen(current) + 1 + strlen(path) > 76 && has_path) {
            char *line = ml_format("%s \\", current);
            PUSH(includes, line);
            current = " ";
            has_path = false;
        }
        current = ml_format("%s %s", current, path);
        has_path = true;
    }
    PUSH(includes, current);
    StringList macros = {0};
    PUSH(macros, "== history ==");
    for (int i = 0; i < p->history.count; ++i)
        PUSH(macros, p->history.items[i]);
    PUSH(macros, "");
    PUSH(macros, "== table ==");
    MacroList table = sorted_macros(p);
    for (int i = 0; i < table.count; ++i) {
        Macro *macro = table.items[i];
        macro->references = (StringList){0};
        for (int j = 0; j < macro->replacement.count; ++j) {
            Token token = macro->replacement.items[j];
            if (equal(token.kind, "identifier") && find_macro(p, token.spelling) &&
                !string_member(macro->parameters, token.spelling))
                string_insert(&macro->references, token.spelling);
        }
        if (macro->references.count > 1)
            qsort(macro->references.items, (size_t)macro->references.count, sizeof(char *),
                  string_compare);
    }
    int objects = 0;
    for (int i = 0; i < table.count; ++i) {
        Macro *macro = table.items[i];
        char *definition = macro->replacement.count ? ml_format("#define %s %s", signature(macro),
                                                                render(macro->replacement))
                                                    : ml_format("#define %s", signature(macro));
        PUSH(macros, definition);
        MacroList seen = {0};
        bool recursive = recursive_visit(p, macro, macro, &seen);
        char *location =
            ml_format("  at %s expanded=%d tested=%d recursive=%s", position_text(macro->position),
                      macro->expanded, macro->tested, recursive ? "yes" : "no");
        PUSH(macros, location);
        Text refs = {0};
        text_add(&refs, "  refs:");
        for (int j = 0; j < macro->references.count; ++j) {
            text_char(&refs, ' ');
            text_add(&refs, macro->references.items[j]);
        }
        char *references = text_value(&refs);
        PUSH(macros, references);
        if (!macro->function)
            ++objects;
    }
    PUSH(macros, "");
    char *totals = ml_format("macros=%d object_like=%d function_like=%d", table.count, objects,
                             table.count - objects);
    PUSH(macros, totals);
    StringList names = {0};
    for (int i = 0; i < p->ever_defined.count; ++i)
        PUSH(names, p->ever_defined.items[i]);
    if (names.count > 1)
        qsort(names.items, (size_t)names.count, sizeof(char *), string_compare);
    Text undefined = {0};
    text_add(&undefined, "undefined:");
    for (int i = 0; i < names.count; ++i)
        if (!find_macro(p, names.items[i])) {
            text_char(&undefined, ' ');
            text_add(&undefined, names.items[i]);
        }
    char *undefined_line = text_value(&undefined);
    PUSH(macros, undefined_line);
    char *builtins_line =
        ml_format("builtins: __COUNTER__=%d __FILE__=%d __LINE__=%d", p->builtin_counts[0],
                  p->builtin_counts[1], p->builtin_counts[2]);
    PUSH(macros, builtins_line);
    StringList conditions = {0};
    for (int i = 0; i < p->conditionals.count; ++i)
        PUSH(conditions, p->conditionals.items[i]);
    PUSH(conditions, "");
    PUSH(conditions, "== skipped regions ==");
    for (int i = 0; i < p->regions.count; ++i)
        PUSH(conditions, p->regions.items[i]);
    PUSH(conditions, "");
    char *condition_totals = ml_format(
        "directives=%d taken=%d not_taken=%d skipped=%d not_evaluated=%d endif=%d regions=%d",
        p->conditionals.count, p->condition_counts[0], p->condition_counts[1],
        p->condition_counts[2], p->condition_counts[3], p->condition_counts[4], p->regions.count);
    PUSH(conditions, condition_totals);
    char *diagnostics_totals = ml_format("errors=%d warnings=%d", p->errors, p->warnings);
    PUSH(p->diagnostics, diagnostics_totals);
    mkdir("output", 0777);
    write_lines("preprocessed.txt", p->output);
    write_lines("includes.txt", includes);
    write_lines("macros.txt", macros);
    write_lines("conditionals.txt", conditions);
    write_lines("diagnostics.txt", p->diagnostics);
}
int main(void) {
    Preprocessor *p = ml_alloc(sizeof(*p));
    PUSH(p->tree, "main.c");
    process_defines(p);
    marker(p, "main.c", 1, 0);
    process_file(p, "main.c", 0);
    MacroList macros = sorted_macros(p);
    for (int i = 0; i < macros.count; ++i)
        unused_check(p, macros.items[i]);
    write_reports(p);
    ml_cleanup();
    return 0;
}

